            (void)(m_assertAlmostEqual(Args({V(0.5), (rd(pvz::getattr(L_b, SY("_grave_progress")), L_uid) - L_before)}, {{SY("places"), V(6.0)}})));
            setm(L_grave, &Obj::冰冻, SV("冰冻"), V(900.0));
