V C_PvP59Tests::m_battle(const Args& A) {
    V L_plants = (A.size() > 0 || A.has_kw(SY("plants"))) ? A.get(0, SY("plants"), nullptr) : V(V::none());
    V L_zombies = (A.size() > 1 || A.has_kw(SY("zombies"))) ? A.get(1, SY("zombies"), nullptr) : V(V::none());
    V L_water = (A.size() > 2 || A.has_kw(SY("water"))) ? A.get(2, SY("water"), nullptr) : V(V(false));
    V L_opening_cooldowns = (A.size() > 3 || A.has_kw(SY("opening_cooldowns"))) ? A.get(3, SY("opening_cooldowns"), nullptr) : V(V(false));
    V L_night = (A.size() > 4 || A.has_kw(SY("night"))) ? A.get(4, SY("night"), nullptr) : V(V(false));
    V L_rule_changes = A.kwrest({"self", "plants", "zombies", "water", "opening_cooldowns", "night"});
    V L_b;
    V L_data;
    V L_player;
    V L_rules;
    V L_terrain;
    L_rules = py::dict_of(pm_catalog::RULES, {{SV("plant_start"), V(5000.0)}, {SV("night_plant_start"), V(5000.0)}, {SV("zombie_start"), V(5000.0)}, {SV("night_zombie_start"), V(5000.0)}});
    (void)(callm(L_rules, SY("update"), Args{L_rule_changes}));
    L_terrain = pm_test_pvp_native_battle_combat::f_field(Args{L_water});
    if ((L_night).truthy()) {
        L_data = callm(L_terrain, SY("to_dict"), Args{});
        (void)(callm(L_data, SY("pop"), Args{SV("terrain_hash"), V::none()}));
        pvz::setitem(rd(L_data, SV("environment")), SV("night"), V(true));
        L_terrain = pm_maps::C_MapSnapshot::m_from_dict(Args{L_data});
    }
    L_b = pm_native_battle::new_NativeBattle(Args({L_terrain, py_dict({{SV("plant"), py_or(L_plants, [&]() -> V { return V::list({SV("plant:向日葵"), SV("plant:豌豆射手"), SV("plant:花盆")}); })}, {SV("zombie"), py_or(L_zombies, [&]() -> V { return V::list({SV("zombie:脑光墓碑"), SV("zombie:普通僵尸")}); })}})}, {{SY("rules"), L_rules}, {SY("bridge"), a_bridge}, {SY("pygame"), a_pg}}));
    (void)(m_addCleanup(Args{pvz::getattr(L_b, SY("close"))}));
    if (!(L_opening_cooldowns).truthy()) {
        { V it1_ = py::iter_list(callm(pvz::getattr(L_b, SY("players")), SY("values"), Args{}));
        for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) {
            L_player = it1_.idx(int64_t(i1_)); 
            (void)(callm(rd(L_player, SV("cooldowns")), SY("clear"), Args{}));
        }}
    }
    return L_b;
    return V::none();
}

